function h(string $v): string {return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function redirect_view(string $v): never {header('Location:/?view='.rawurlencode($v));exit;}
function entity_create_extended(string $uid,array $in): array {
 $type=(string)($in['type']??'');$name=trim((string)($in['name']??''));
 if(!in_array($type,['page','business','community','event','opportunity','place'],true)||mb_strlen($name)<2)return[false,'أكمل بيانات الإنشاء.'];
 $e=oyya_read('entities');$e[]=['id'=>oyya_id(),'owner_id'=>$uid,'type'=>$type,'name'=>$name,'description'=>trim((string)($in['description']??'')),'city'=>trim((string)($in['city']??'')),'address'=>trim((string)($in['address']??'')),'contact'=>trim((string)($in['contact']??'')),'lat'=>(float)($in['lat']??0),'lng'=>(float)($in['lng']??0),'created_at'=>oyya_now()];oyya_write('entities',$e);return[true,'تم الإنشاء.'];
}

