 elseif($a==='logout'){oyya_logout();header('Location:/');exit;}
 else{
  $user=oyya_current_user();if(!$user){header('Location:/');exit;}$uid=(string)$user['id'];$ok=true;
  if($a==='post')[$ok,$message]=oyya_create_media_post($uid,$_POST,$_FILES['media']??null);
  elseif($a==='like')oyya_toggle_like($uid,(string)($_POST['post_id']??''));
  elseif($a==='save')oyya_toggle_save($uid,(string)($_POST['post_id']??''));
  elseif($a==='comment')[$ok,$message]=oyya_add_comment($uid,(string)($_POST['post_id']??''),(string)($_POST['text']??''));
  elseif($a==='audio_comment')[$ok,$message]=oyya_add_audio_comment($uid,(string)($_POST['post_id']??''),$_FILES['voice']??[]);
  elseif($a==='follow')oyya_toggle_follow($uid,(string)($_POST['target_id']??''));
  elseif($a==='friend')[$ok,$message]=oyya_friend_request($uid,(string)($_POST['target_id']??''));
  elseif($a==='friend_respond')oyya_friend_respond($uid,(string)($_POST['request_id']??''),(string)($_POST['status']??'declined'));
  elseif($a==='profile')[$ok,$message]=oyya_profile_update($uid,$_POST);
  elseif($a==='location')[$ok,$message]=oyya_location_set($uid,(float)($_POST['lat']??999),(float)($_POST['lng']??999));
  elseif($a==='entity')[$ok,$message]=entity_create_extended($uid,$_POST);
  elseif($a==='membership')oyya_toggle_membership($uid,(string)($_POST['entity_id']??''));
  elseif($a==='gallery')[$ok,$message]=oyya_entity_gallery_add($uid,(string)($_POST['entity_id']??''),$_FILES['media']??[],(string)($_POST['caption']??''));
  elseif($a==='message')[$ok,$message]=oyya_send_message($uid,(string)($_POST['to_id']??''),(string)($_POST['text']??''));
  elseif($a==='notifications_read'){oyya_mark_notifications_read($uid);$message='تم تعليم النشاط كمقروء.';}
  elseif($a==='verify')[$ok,$message]=oyya_request_verification($uid);
  elseif($a==='reel'){$upload=oyya_upload_media($uid,$_FILES['video']??[],'reel');if($upload[0])[$ok,$message]=oyya_create_reel($uid,(string)($_POST['caption']??''),(string)$upload[1]);else{$ok=false;$message=(string)$upload[1];}}
  elseif($a==='album'){[$ok,$albumId]=oyya_create_album($uid,(string)($_POST['title']??''));if($ok&&isset($_FILES['media'])&&($_FILES['media']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK){$up=oyya_upload_media($uid,$_FILES['media'],'album');if($up[0])oyya_album_add($uid,(string)$albumId,(string)$up[1]);}$message=$ok?'تم إنشاء الألبوم.':(string)$albumId;}
  elseif($a==='ad')[$ok,$message]=oyya_create_ad($uid,$_POST);
  elseif($a==='game_create'){[$ok,$id]=oyya_create_game_room($uid,(string)($_POST['name']??''),(int)($_POST['max_players']??6));$message=$ok?'تم إنشاء الطاولة.':(string)$id;}
  elseif($a==='game_join')[$ok,$message]=oyya_join_game($uid,(string)($_POST['room_id']??''));
  elseif($a==='game_play')[$ok,$message]=oyya_game_play($uid,(string)($_POST['room_id']??''));
  elseif($a==='delete_account'){if(oyya_delete_account($uid)){oyya_logout();header('Location:/');exit;}else{$ok=false;$message='تعذر حذف الحساب.';}}
  $error=!$ok;$ret=(string)($_POST['return_view']??'feed');redirect_view(preg_replace('/[^a-z_]/','',$ret)?:'feed');
 }
