</section><aside class="panel side"><b>حولك الآن</b><p class="muted"><?=$usersCount?> مستخدم من 20</p><a href="/?view=people">اكتشف الأشخاص</a><a href="/?view=events">الأحداث</a><a href="/?view=pages">الأعمال</a><a href="/?view=games">طاولات اللعب</a></aside></div></main>
<div class="audioDock" id="audioDock"><button class="round" type="button" id="radioToggle">▶</button><div class="audioMain"><b>راديو OYYA</b><div class="muted" id="audioMeta" style="font-size:12px">اضغط تشغيل للاستماع أثناء تصفح العالم</div></div><label class="check"><input type="checkbox" id="adhanToggle"> الأذان</label><input class="volume" id="volume" type="range" min="0" max="1" step="0.01" value="0.25"></div>
<?php endif;?></div><script>
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('on'));document.querySelectorAll('.form').forEach(x=>x.classList.remove('on'));b.classList.add('on');document.getElementById(b.dataset.target)?.classList.add('on')}));
if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
const geoBtn=document.getElementById('geoBtn');if(geoBtn)geoBtn.addEventListener('click',()=>{if(!navigator.geolocation)return alert('الموقع غير مدعوم');geoBtn.disabled=true;navigator.geolocation.getCurrentPosition(p=>{document.getElementById('lat').value=p.coords.latitude;document.getElementById('lng').value=p.coords.longitude;document.getElementById('locationForm').submit()},()=>{geoBtn.disabled=false;alert('لم يتم السماح بالموقع')},{enableHighAccuracy:false,timeout:12000})});
for(const btn of document.querySelectorAll('.recordVoice'))btn.addEventListener('click',async()=>{const form=btn.closest('.voiceForm'),input=form.querySelector('.voiceInput');if(!navigator.mediaDevices||!window.MediaRecorder){input.click();return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const rec=new MediaRecorder(stream);const chunks=[];rec.ondataavailable=e=>chunks.push(e.data);rec.onstop=()=>{const blob=new Blob(chunks,{type:rec.mimeType||'audio/webm'});const file=new File([blob],'voice.webm',{type:blob.type});const dt=new DataTransfer();dt.items.add(file);input.files=dt.files;stream.getTracks().forEach(t=>t.stop());btn.textContent='✓ تم التسجيل';};rec.start();btn.textContent='⏹ إيقاف';btn.onclick=()=>rec.stop();}catch(e){input.click()}});
const radioBtn=document.getElementById('radioToggle');if(radioBtn){const meta=document.getElementById('audioMeta'),vol=document.getElementById('volume'),adhan=document.getElementById('adhanToggle');adhan.checked=localStorage.getItem('oyya_adhan')==='1';adhan.addEventListener('change',()=>{localStorage.setItem('oyya_adhan',adhan.checked?'1':'0');meta.textContent=adhan.checked?'الأذان مفعّل لهذا الجهاز':'الأذان متوقف'});let ctx=null,gain=null,timer=null,i=0;const seq=[220,261.63,329.63,392,329.63,261.63];function tone(){const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=seq[i++%seq.length];g.gain.setValueAtTime(.001,ctx.currentTime);g.gain.linearRampToValueAtTime(.08,ctx.currentTime+.05);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.7);o.connect(g);g.connect(gain);o.start();o.stop(ctx.currentTime+.75)}async function start(){ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();await ctx.resume();gain=gain||ctx.createGain();if(!gain._x){gain.connect(ctx.destination);gain._x=1}gain.gain.value=Number(vol.value);tone();timer=setInterval(tone,800);radioBtn.textContent='❚❚';meta.textContent='OYYA Radio · بث تجريبي مستمر داخل التطبيق'}function stop(){clearInterval(timer);timer=null;if(gain&&ctx)gain.gain.value=0;radioBtn.textContent='▶';meta.textContent='متوقف'}radioBtn.addEventListener('click',()=>timer?stop():start());vol.addEventListener('input',()=>{if(gain)gain.gain.value=Number(vol.value)})}
</script></body></html>